mapper.insert:
insert into lecture(
	lecture_no, lecture_title, lecture_category, lecture_duration, lecture_price, lecture_type
)
values(
	#{lecture_no}, #{lecture_title}, #{lecture_category}, #{lecture_duration}, #{lecture_price}, #{lecture_type}
)

mapper.select:
select * from (
	select rownum rn, TMP.* from(

		where #{lastLectureNo} > lecture_no 

		order by lecture_no desc
	) TMP
) where rn between 1 and #{size}
